filldraw((-2,-2)--(-2,2)--(2,2)--(2,-2)--cycle,gray(0.7));
draw((-2.5,0)--(2.5,0));
draw((0,-2.5)--(0,2.5));

dot("$2$", (2,0), SE);
dot("$2$", (0,2), NW);
dot("$-2$", (-2,0), SW);
dot("$-2$", (0,-2), SW);
[/asy]

